<script>
import BtnSubSideBar from "@/components/Btn/BtnSubSideBar";

export default {
  name: "AppSidebar",
  components: {
    BtnSubSideBar,
  },
  props: {
    // 用來儲存權限對照結果
    permissionMap: {},
    notificationBoxConfirmFlag: Boolean,
  },
  data() {
    return {
      dropDownFlag: {
        Course: false,
        PlanTemplate: false,
        Order: false,
        Setting: false,
      },
      showElement: {
        Course: false,
        PlanTemplate: false,
        Order: false,
        Setting: false,
      },
    };
  },
  created() {
    this.setScrollWithWindow();
  },
  methods: {
    openDropdown(key) {
      this.showElement.Course = false;
      this.showElement.Order = false;
      this.showElement.PlanTemplate = false;
      this.showElement.Setting = false;
      this.dropDownFlag.Course = false;
      this.dropDownFlag.Order = false;
      this.dropDownFlag.PlanTemplate = false;
      this.dropDownFlag.Setting = false;

      this.showElement[key] = true;
      this.dropDownFlag[key] = true;
    },
    closeDropdown(key) {
      this.dropDownFlag[key] = false; // 播放消失動畫
    },
    handleAnimationEnd(key) {
      if (!this.dropDownFlag[key]) {
        // 消失動畫播完後，才真正隱藏元素
        this.showElement[key] = false;
      }
    },
    redirect(page) {
      if (this.$route.path === page) {
        this.$emit("refreshPage");
      } else {
        this.$router.push(page);
      }
    },
    setScrollWithWindow() {
      // 讓側邊欄跟著視窗移動
      window.addEventListener("scroll", () => {
        const header = document.querySelector(".headerContainer");
        const sidebar = document.querySelector(".sidebarCard");
        const headerBottom = header.getBoundingClientRect().bottom;

        if (headerBottom <= 80) {
          if (headerBottom <= 0) sidebar.style.top = 0;
          else sidebar.style.top = headerBottom + "px";
        } else {
          sidebar.style.top = "auto";
        }
      });
    },
  },
  computed: {
    groupClassFlag() {
      return (
        this.permissionMap.EditGroupClassShowcase ||
        this.permissionMap.SelectGroupClassShowcase ||
        this.permissionMap.EditGroupClassSchedule ||
        this.permissionMap.SelectGroupClassSchedule ||
        this.permissionMap.EditMemberClass ||
        this.permissionMap.SelectMemberClass
      );
    },
    planTemplateFlag() {
      return this.permissionMap.EditPlan || this.permissionMap.SelectPlan;
    },
    orderFlag() {
      return (
        this.permissionMap.EditOrder ||
        this.permissionMap.SelectOrder ||
        this.permissionMap.AddOrder
      );
    },
    settingFlag() {
      return this.permissionMap.EditOrder;
    },
  },
  mounted() {
    this.$emit("getPermission");
  },
};
</script>


<style scoped>
.sidebarCard {
  position: fixed;
  top: 58px;
  width: 200px;
  height: 100vh;
  border-radius: 3px;
  background: #e0e0e0;
  overflow-y: auto;
}

.sidebarRow {
  display: flex;
  align-items: center;
  justify-content: start;
  margin-left: 15px;
  margin-top: 15px;
}

.sidebarIcon {
  margin-right: 8px;
}

.btnSidebar,
.btnDropDownSidebar {
  background-color: #e0e0e0;
  border: none;
  padding: 5px;
  font-size: 1rem;
  width: 170px;
  border-radius: 1rem;
  cursor: pointer;
  display: flex;
  justify-content: left;
  align-items: center;
}

.btnSidebar:active {
  transform: translateY(0.2rem);
}

.btnSidebar:hover,
.btnDropDownSidebar:hover {
  background: #eee;
}

.sidebarSymbol {
  margin-left: 70px;
}
</style>

<style scoped>
.showDropdown {
  animation: flip-in-hor-bottom 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94) both;
}

.hideDropdown {
  animation: flip-out-hor-top 0.45s cubic-bezier(0.55, 0.085, 0.68, 0.53) both;
}

@keyframes flip-in-hor-bottom {
  0% {
    transform: rotateX(80deg);
    opacity: 0;
  }
  100% {
    transform: rotateX(0);
    opacity: 1;
  }
}

@keyframes flip-out-hor-top {
  0% {
    transform: rotateX(0);
    opacity: 1;
  }
  100% {
    transform: rotateX(70deg);
    opacity: 0;
  }
}
</style>